(function(){'use strict';
var canvas=document.getElementById('scene'),ctx=canvas.getContext('2d'),status=document.getElementById('status'),out=document.getElementById('log');
var FPS=24,N=240,MAX=4*1024*1024,busy=false,job=0,cancelWork=null,videoBlob=null,route='',started=0;
var buttons=['replay','wc','mr','editor'],lines=[];
function log(s){lines.push(new Date().toISOString().slice(11,19)+' '+s);if(lines.length>90)lines.shift();out.textContent=lines.join('\n');}
function say(s){status.textContent=s;log(s);}
function error(e){return e&&(e.errMsg||e.message)||String(e);}
function platform(){return window.xhs&&window.xhs.miniTool;}
function lock(v){busy=v;buttons.forEach(function(id){document.getElementById(id).disabled=v||(id==='editor'&&!videoBlob);});document.getElementById('stop').disabled=!v;}
function check(id){if(id!==job||document.hidden)throw Error('已停止：取消或页面离开前台');}
function delay(ms){return new Promise(function(r){setTimeout(r,ms);});}
function timeout(p,ms,label){return new Promise(function(resolve,reject){var t=setTimeout(function(){reject(Error(label+'超时'));},ms);p.then(function(v){clearTimeout(t);resolve(v);},function(e){clearTimeout(t);reject(e);});});}
function draw(t){
 var w=360,h=640,g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#a9dcf2');g.addColorStop(1,'#fff4e5');ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
 ctx.fillStyle='rgba(255,255,255,.7)';for(var c=0;c<5;c++){ctx.beginPath();ctx.ellipse((c*103+30+t*5)%450-40,115+c*74,76,19,0,0,Math.PI*2);ctx.fill();}
 var x=180+Math.sin(t*.85)*94,y=485-t*33+Math.sin(t*2)*18,r=44+Math.sin(t*1.3)*5;
 for(var i=0;i<16;i++){var a=i*2.399+t*.3,rr=65+18*Math.sin(t+i);ctx.fillStyle='rgba(255,255,255,.65)';ctx.beginPath();ctx.arc(x+Math.cos(a)*rr,y+Math.sin(a)*rr,2+i%3,0,7);ctx.fill();}
 var b=ctx.createRadialGradient(x-r*.3,y-r*.4,2,x,y,r);b.addColorStop(0,'rgba(255,255,255,.9)');b.addColorStop(.35,'rgba(220,247,255,.16)');b.addColorStop(.8,'rgba(208,190,250,.26)');b.addColorStop(1,'rgba(255,255,255,.95)');ctx.fillStyle=b;ctx.beginPath();ctx.arc(x,y,r,0,7);ctx.fill();ctx.strokeStyle='rgba(255,255,255,.85)';ctx.lineWidth=2;ctx.stroke();
 ctx.fillStyle='#305b76';ctx.textAlign='center';ctx.font='bold 23px sans-serif';ctx.fillText('泡泡的 10 秒小旅行',180,48);ctx.font='14px sans-serif';ctx.fillText('固定轨迹 · 视频能力实验',180,75);ctx.fillText(Math.min(10,t).toFixed(1)+' / 10.0 s',180,599);ctx.fillStyle='#719db6';ctx.fillRect(30,620,300*Math.min(1,t/10),3);
}
async function animate(id,recording){var start=performance.now();while(true){check(id);var t=Math.min((performance.now()-start)/1000,10);draw(t);if(t>=10)break;await delay(1000/FPS);}if(recording)await delay(45);}
async function wc(id){
 if(typeof window.VideoEncoder!=='function'||typeof window.VideoFrame!=='function'||typeof VideoEncoder.isConfigSupported!=='function')throw Error('WebCodecs 不可用');
 var config={codec:'avc1.42001e',width:360,height:640,framerate:FPS,bitrate:700000,latencyMode:'realtime',avc:{format:'avc'}},support=await timeout(VideoEncoder.isConfigSupported(config),5000,'编码能力检测');check(id);if(!support.supported)throw Error('H.264 AVC 配置不支持');
 log('H.264 配置支持；开始实际编码 240 帧');var samples=[],avcc=null,total=0,encoderError=null;
 var enc=new VideoEncoder({output:function(chunk,meta){var data=new Uint8Array(chunk.byteLength);chunk.copyTo(data);total+=data.length;if(total>MAX){encoderError=Error('编码超过 4 MiB 上限');return;}samples.push({data:data,key:chunk.type==='key',timestamp:chunk.timestamp});if(meta.decoderConfig&&meta.decoderConfig.description)avcc=new Uint8Array(meta.decoderConfig.description).slice();},error:function(e){encoderError=e;}});
 cancelWork=function(){if(enc.state!=='closed')enc.close();};
 try{enc.configure(config);for(var i=0;i<N;i++){check(id);if(encoderError)throw encoderError;draw(i/FPS);var frame=new VideoFrame(canvas,{timestamp:Math.round(i*1000000/FPS),duration:Math.round(1000000/FPS)});try{enc.encode(frame,{keyFrame:i%48===0});}finally{frame.close();}if(i%12===11){await timeout(enc.flush(),8000,'编码排空');await delay(0);}}await timeout(enc.flush(),8000,'最终编码');check(id);if(encoderError)throw encoderError;if(samples.length!==N)throw Error('帧数不完整 '+samples.length+'/'+N);var bytes=BubbleMP4.mux(samples,avcc,360,640,FPS);log('实际输出 '+samples.length+' 帧；10.000 秒；MP4 '+bytes.length+' 字节');return new Blob([bytes],{type:'video/mp4'});}finally{if(enc.state!=='closed')enc.close();cancelWork=null;}
}
function recorderType(){if(typeof window.MediaRecorder!=='function'||typeof MediaRecorder.isTypeSupported!=='function')return '';var ts=['video/mp4;codecs=avc1.42E01E','video/mp4;codecs=avc1','video/mp4'];for(var i=0;i<ts.length;i++){try{if(MediaRecorder.isTypeSupported(ts[i]))return ts[i];}catch(e){}}return '';}
async function mr(id){var mime=recorderType();if(!mime||typeof canvas.captureStream!=='function')throw Error('MediaRecorder MP4 / Canvas captureStream 不支持；不以 WebM 假充 MP4');draw(0);var stream=canvas.captureStream(FPS),rec,chunks=[],bytes=0,recError=null,done;
 try{rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:700000});done=new Promise(function(resolve,reject){rec.ondataavailable=function(e){if(e.data&&e.data.size){bytes+=e.data.size;if(bytes>MAX){recError=Error('录制超过 4 MiB 上限');if(rec.state!=='inactive')rec.stop();}else chunks.push(e.data);}};rec.onerror=function(e){recError=e.error||Error('MediaRecorder 异常');reject(recError);};rec.onstop=resolve;});done.catch(function(){});cancelWork=function(){if(rec.state!=='inactive')rec.stop();stream.getTracks().forEach(function(t){t.stop();});};rec.start(500);log('已开始实际录制 '+mime);await animate(id,true);if(rec.state!=='inactive')rec.stop();await timeout(done,5000,'录制结束');check(id);if(recError)throw recError;if(!bytes)throw Error('录制结果为空');var actual=rec.mimeType||mime;if(actual.toLowerCase().indexOf('video/mp4')!==0)throw Error('实际返回不是 MP4：'+actual);log('录制输出 '+bytes+' 字节；时长需在手机编辑页核验');return new Blob(chunks,{type:'video/mp4'});}finally{if(rec&&rec.state!=='inactive')rec.stop();stream.getTracks().forEach(function(t){t.stop();});cancelWork=null;}}
function read(blob,method){return new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(){resolve(r.result);};r.onerror=function(){reject(Error('文件读取失败'));};r[method](blob);});}
async function validate(blob){if(!blob.size||blob.size>MAX)throw Error('视频体积无效');var bytes=new Uint8Array(await read(blob,'readAsArrayBuffer'));if(bytes.length<12||String.fromCharCode.apply(null,bytes.slice(4,8))!=='ftyp')throw Error('输出不是有效 MP4 文件头');}
async function run(kind){if(busy)return;var id=++job;videoBlob=null;lock(true);started=Date.now();say(kind==='replay'?'正在重演…':'正在生成，请保持页面在前台…');try{if(kind==='replay'){await animate(id,false);check(id);say('重演完成。这只是动画，不代表能导出视频。');}else{var result=kind==='wc'?await wc(id):await mr(id);await validate(result);check(id);videoBlob=result;route=kind;say('MP4 已生成 '+(result.size/1024).toFixed(0)+' KB，用时 '+((Date.now()-started)/1000).toFixed(1)+' 秒。可点下方带入编辑页。');}}catch(e){say('本次未生成可用视频：'+error(e)+'。可换另一条路线或只看重演。');}finally{lock(false);}}
async function editor(){if(busy||!videoBlob)return;var p=platform();if(!p||typeof p.writeTempFile!=='function'||typeof p.postNote!=='function'){say('当前环境没有 writeTempFile / postNote；仅编码完成，未验证手机编辑页。');return;}var id=++job;lock(true);say('写入临时 MP4…');try{var data=await read(videoBlob,'readAsDataURL');check(id);var file=await timeout(p.writeTempFile({data:data}),15000,'writeTempFile');check(id);if(!file||typeof file.filePath!=='string'||!file.filePath)throw Error('未返回临时文件路径');log('writeTempFile 成功，路线 '+route);say('已请求打开视频编辑页。请检查画面与时长后取消，不要发布。');var pending=p.postNote({pageType:'video_publish',mediaInfo:{video_resources:{video_url:file.filePath}}});if(pending&&typeof pending.then==='function'){pending.then(function(){log('postNote 返回成功回调，不据此判断视频播放或审核结果');},function(e){log('postNote 返回：'+error(e)+'（可能是用户取消）');});}}catch(e){say('未完成编辑页验证：'+error(e));}finally{lock(false);}}
buttons.slice(0,3).forEach(function(id){document.getElementById(id).addEventListener('click',function(){run(id);});});document.getElementById('editor').addEventListener('click',editor);
function stop(){if(!busy)return;job++;if(cancelWork)cancelWork();say('已停止，未生成结果；可重新尝试。');}
document.getElementById('stop').addEventListener('click',stop);document.addEventListener('visibilitychange',function(){if(document.hidden)stop();});
if(!ctx){say('Canvas 2D 不支持，实验不可运行');buttons.forEach(function(id){document.getElementById(id).disabled=true;});return;}draw(0);var p=platform();log('probe-0.1.0 · 360×640 · 24fps · 10s · 无音轨');log('WebCodecs='+!!window.VideoEncoder+' / VideoFrame='+!!window.VideoFrame);log('MediaRecorder MP4='+recorderType()+' / captureStream='+(typeof canvas.captureStream==='function'));log('writeTempFile='+!!(p&&p.writeTempFile)+' / postNote='+!!(p&&p.postNote));say('选择一种编码方式测试。接口存在不等于编码成功。');
})();
